Method.Source:
/// <summary>
/// Handles logic when a field is modified on the SalesParmTable.
/// If the TransDate field is modified and the document is an invoice,
/// updates DSD positions for all related sales lines.
/// </summary>
/// <param name="_fieldId">The ID of the modified field.</param>
public void modifiedField(FieldId _fieldId)
{
    SalesLine salesLine;
    SalesParmLine salesParmLine;

    next modifiedField(_fieldId);

    switch (_fieldId)
    {
        case fieldnum(SalesParmTable, TransDate):

            // If the document is an invoice, update DSD positions for all related sales lines
            if (this.Ordering == DocumentStatus::Invoice)
            {
                ttsbegin;

                while select salesLine where SalesLine.SalesId == this.SalesId
                exists join salesParmLine
                where salesParmLine.ParmId == this.ParmId &&
                    salesParmLine.SalesLineRecId  == salesLine.RecId
                {
                    SalesFormLetter_Invoice::updateDSDPostitions_AVA(salesLine, this.ParmId, this.Transdate);
                }

                ttscommit;
            }

            // Call additional logic for document date modification
            this.transOfDocumentDateModified();
            break;
    }
}
